// App.js
import React from 'react';
import ReactDOM from 'react-dom';
import { Link } from 'carbon-components-react';
import 'carbon-components/css/carbon-components.min.css';

function App() {
  return (
    <div style={{ padding: '2rem', fontFamily: 'IBM Plex Sans, sans-serif' }}>
      <h2>Inline Link Variant</h2>

      {/* Light background */}
      <div style={{ background: '#ffffff', padding: '1rem', marginBottom: '1rem' }}>
        <p>
          Light bg: this is an <Link inline href="https://example.com">inline link</Link>.
        </p>
        <p>
          Hover me:&nbsp;
          <Link inline href="https://example.com">hover link</Link>
        </p>
        <p>
          Active (click and hold):&nbsp;
          <Link inline href="https://example.com" onMouseDown={() => { }}>active link</Link>
        </p>
        <p>
          Focus (tab to):&nbsp;
          <Link inline href="https://example.com" tabIndex={0}>focus link</Link>
        </p>
        <p>
          Disabled:&nbsp;
          <Link inline disabled href="https://example.com">disabled link</Link>
        </p>
        <p>
          Visited (click to visit then reload):&nbsp;
          <Link inline href="https://example.com">visited link</Link>
        </p>
      </div>

      {/* Gray background */}
      <div style={{ background: '#f4f4f4', padding: '1rem', marginBottom: '1rem' }}>
        <p style={{ color: '#161616' }}>
          Gray bg: <Link inline href="https://example.com">inline link</Link>
        </p>
      </div>

      {/* Dark background */}
      <div style={{ background: '#161616', padding: '1rem', color: '#f4f4f4' }}>
        <p>
          Dark bg: <Link inline href="https://example.com">inline link</Link>
        </p>
      </div>
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
